        bail_invalid_request!(param = "suffix", "suffix is not supported.");
    }

    if let Some(logprobs) = request.logprobs
        && logprobs > i32::MAX as u32
    {
        bail_invalid_request!(
            param = "logprobs",
            "`logprobs` must fit within a signed 32-bit integer."
        );
    }

